{
  "title": "Team Lunch Fund",
  "description": "Manual payout, admin decides when and where",
  "potType": "private",
  "refundType": "admin",
  "minContribution": 50000,
  "payoutMode": "manual",
  "payoutConfig": {}
}

{
  "title": "Team Lunch Fund (fixed destination)",
  "description": "Manual payout, but always to the same pre-agreed account",
  "potType": "private",
  "refundType": "admin",
  "minContribution": 50000,
  "payoutMode": "manual",
  "payoutConfig": {
    "destinationAccount": "{{destinationAccount}}",
    "destinationBank": "{{destinationBank}}"
  }
}

{
  "title": "Ajo Rotation Group",
  "description": "Each member takes a turn receiving the payout",
  "potType": "private",
  "refundType": "contributors",
  "minContribution": 100000,
  "payoutMode": "scheduled",
  "payoutConfig": {
    "ordered": true,
    "legs": [
      {
        "destinationAccount": "{{destinationAccount}}",
        "destinationBank": "{{destinationBank}}",
        "sequenceOrder": 0,
        "amount": 5000000,
        "scheduledDate": "2026-08-01T00:00:00.000Z"
      },
      {
        "destinationAccount": "{{memberDestinationAccount}}",
        "destinationBank": "{{memberDestinationBank}}",
        "sequenceOrder": 1,
        "amount": 5000000,
        "scheduledDate": "2026-09-01T00:00:00.000Z"
      }
    ]
  }
}
